"""Write docs/korea_links.md from docs/korea_links_check.json (made by pipeline/verify_korea.py).

    python pipeline/verify_korea.py && python pipeline/korea_links_doc.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    r = json.loads((ROOT / "docs" / "korea_links_check.json").read_text(encoding="utf-8"))
    pct = lambda x: "—" if x is None else f"{x * 100:.1f} %"
    L = ["# Direct links to Earth via Yeoju KDSA and the NASA DSN (card 16)\n",
         "Generated by `python pipeline/verify_korea.py` + `python pipeline/korea_links_doc.py` "
         "(numbers: `docs/korea_links_check.json`). Window: every hour 2026-01-01T00Z – 2030-12-31T23Z (43,824 h).\n",
         "**Definition (same as the app):** a link hour = the Earth's centre is above the site's real terrain horizon "
         "(2 m observer) **and** the Moon's centre is ≥ 10° above the ground station's horizon. Direct link only: no relay, "
         "no link budget, no antenna schedule or availability. Stations: KDSA (Yeoju, 35 m; NAIF `kdsa01.tf`, use pending), "
         "DSN Goldstone DSS-14, Madrid DSS-63, Canberra DSS-43 (DSN 810-005 module 301 Rev. P).\n",
         "## 1. All 33 sites\n",
         "| Site | Earth visible (h) | KDSA link (h) | KDSA share | any DSN link (h) | DSN share | KDSA only, no DSN (h) |",
         "|---|---|---|---|---|---|---|"]
    for s in r["sites"]:
        L.append(f"| {s['id']} | {s['earth_h']:,} | {s['kdsa_h']:,} | {pct(s['kdsa_share'])} | {s['dsn_h']:,} | "
                 f"{pct(s['dsn_share'])} | {s['kdsa_only_h']} |")
    only = [s["kdsa_only_share"] for s in r["sites"] if s["kdsa_only_share"]]
    L.append(f"""
**Reading it.** When the Earth is visible from a site, the three DSN 70 m antennas together see the Moon about
98–99 % of the time, so a 4th station adds little coverage: KDSA alone covers {min(only) * 100:.1f}–{max(only) * 100:.1f} % of
the Earth-visible hours (hours when no DSN complex sees the Moon), e.g. 123 h in 5 years (≈25 h per year) for an
always-Earth-facing site. Its value is redundancy and a second antenna in the Asia–Pacific longitude band (KDSA sees
the Moon 41.6 % of all hours, DSN Canberra 41.9 %). Far-side sites (Chang'e 4, Chang'e 6) never see the Earth, so no
direct link at all; south-polar sites see it only part of the time.
""")
    L += ["## 2. Checks\n", "| Check | Result | Criterion |", "|---|---|---|"]
    for h in r["horizons_random_100"]:
        L.append(f"| Moon az/el at {h['station']} vs JPL Horizons, 100 random hours (seed 16) | max {h['max_deg']:.5f}°, "
                 f"mean {h['mean_deg']:.5f}° | < 0.05° |")
    for h in r["horizons_bits_all_hours"]:
        L.append(f"| {h['station']} Moon ≥ 10° bits, all 43,824 h: Horizons vs `stations.json` | {h['mismatched_hours']} "
                 f"different hour(s), all within {h['max_abs_el_minus_10_at_mismatch_deg']:.4f}° of 10° | only at the threshold |")
    for b in r["brute_force_5_sites"]:
        L.append(f"| Brute force {b['id']} (own Earth-visibility code + Horizons station bits, no `korea_links.py`) | "
                 "difference vs table: " + ", ".join(f"{k} {v:+d}" for k, v in b["diff_vs_table_h"].items())
                 + " h | ≤ 2 h (threshold hours) |")
    L.append(f"| Earth-visible share, own code vs app metrics (actual `core.js`), 33 sites | max difference "
             f"{r['earth_frac_vs_app_metrics_max_abs_diff']:.0e} | identical |")
    L.append("| `python pipeline/korea_links.py --only stations` re-run | station files byte-identical to main | identical |")
    L += ["\n## 3. 30-day KST schedule from 2026-11-14 (1-minute resolution)\n",
          "When can Yeoju (KDSA) talk directly to the site? (Earth visible from the site AND Moon ≥ 10° at Yeoju.) KST = UTC+9.\n"]
    for sid, s in r["schedule_30d_kst"]["sites"].items():
        L.append(f"### {sid} — {s['kdsa_link_minutes'] / 60:.1f} h of KDSA link in 30 days "
                 f"(Earth visible {s['earth_visible_minutes'] / 60:.1f} h)\n")
        L += ["| Date (KST) | Windows |", "|---|---|"]
        for d, ws in s["days_kst"].items():
            L.append(f"| {d} | " + ", ".join(f"{a}–{b}" for a, b in ws) + " |")
        L.append("")
    L += ["## Limits",
          "- Geometry only: no link budget, no antenna time allocation, no KDSA mission constraints.",
          "- Station Moon visibility uses the ellipsoidal horizon (no local terrain at the antenna) and hour marks for the "
          "5-year table; the 30-day schedule uses minute steps with KDSA rise/set to 1 s.",
          "- KDSA coordinates: NAIF `kdsa01.tf`; permission to use them is a pending question to the Seoul organisers.",
          "- SHACKLETON_RIM is the Gläser et al. (2017) rim point S (-89.6866, -162.81) since card 15; its horizon is "
          "card 13's recomputation for that point.", ""]
    (ROOT / "docs" / "korea_links.md").write_text("\n".join(L), encoding="utf-8")
    print("wrote docs/korea_links.md")


if __name__ == "__main__":
    main()
